# ---------------- Regression ----------------
xs = np.array([0,1,2,3.]); ys = np.array([1,3,4,8.])
Xd = np.c_[np.ones(4), xs]; w = np.linalg.solve(Xd.T@Xd, Xd.T@ys); pr = Xd@w; rs = ys-pr
sse = (rs**2).sum(); sst = ((ys-ys.mean())**2).sum()
