# ---------------- Logistic regression ----------------
s0 = 0.5; h0 = sig(s0)
pos = [0.9,0.7,0.4]; neg = [0.8,0.3,0.2,0.1]; auc = np.mean([[p>n for n in neg] for p in pos])
pos2 = pos + [0.3]; auc2 = np.mean([[1 if p>n else 0.5 if p==n else 0 for n in neg] for p in pos2])
